  "공개 호스트 사진 선택": "Choose a public host photo",
  "공개 사진 없음": "No public photo",
  "사진 {0}": "Photo {0}",
  "저장만으로 공개되지 않아요. 모임을 열 때 소개와 이 사진을 다시 확인해요.": "Saving won’t publish this. You’ll confirm the introduction and photo when you create a meetup.",
  "프로필을 수정해도 이미 보낸 신청 내용은 바뀌지 않아요. 취소·거절·탈퇴·차단·모임 종료 후에는 해당 경로의 새 조회가 제한돼요. 이미 본 내용이나 저장한 사진은 회수할 수 없어요.": "Editing your profile won’t change applications you’ve already sent. After a cancellation, decline, leaving, blocking or the meetup ending, new access through that meetup is restricted. Anything already viewed, or photos already saved, can’t be recalled.",
  "안전을 위해 자동 분석과 권한 있는 운영자 검토가 적용돼요.": "Automated safety checks and authorized moderator review apply.",
  "{0} 모임 사진": "{0}'s meetup photo",
  "이름·사진·소개·답변은 신청 당시 공유한 모임 프로필이에요. 이후 프로필을 수정해도 이 신청은 바뀌지 않아요.": "This name, photos, introduction and answer were shared when the application was sent. Later profile edits won’t change this application.",
  "모임 멤버": "Meetup member",
  "모임 호스트": "Meetup host",
  "승인 후에는 선택한 사진·짧은 소개가 멤버에게도 공유돼요. 신청 답변은 호스트만 볼 수 있어요.": "Once approved, your selected photos and short introduction are also shared with members. Only the host sees your application answer.",
  "승인된 멤버에게는 모임 이름만 보여요. 사진·소개 공유는 프로필에서 바꿀 수 있어요.": "Approved members see only your meetup name. You can change photo and introduction sharing in your profile.",
  "이 호스트에게 신청 당시 모임 프로필과 답변을 공유하는 데 동의해요. 다른 신청자에게는 공개되지 않아요. 취소·거절·탈퇴·차단·종료 후 새 조회는 제한되지만 이미 본 내용은 회수할 수 없어요.": "I agree to share my meetup profile and answer with this host as they are now. Other applicants can’t see them. New access is restricted after a cancellation, decline, leaving, blocking or closure, but anything already viewed can’t be recalled.",
  "모임 사진·소개·공개 범위를 따로 설정해요": "Set your meetup photos, introduction and sharing",
