  "{0}는 {1}부터 다시 가능해요. 기존 모임과 신고·차단·나가기는 계속 이용할 수 있어요.": "{0} will be available again from {1}. You can still use your current meetups and report, block or leave.",
  "새 모임 참여": "Joining new meetups",
  "새 행사 개최": "Hosting new events",
  "최근 24시간에 서로 다른 모임에서 2회 이상 나갔어요. 이번에도 승인된 모임에서 종료 전에 처음 나가면 새 모임 참여가 12시간 제한돼요. 자연 종료·승인 전 취소는 제외돼요.": "You’ve left 2 or more different meetups in the last 24 hours. If you leave another approved meetup before it ends, you won’t be able to join new meetups for 12 hours. Meetups that end on their own and cancellations before approval don’t count.",
  "최근 7일에 조기 해산 기록이 있어요. 승인된 참가자가 있는 다른 행사를 조기 해산하면 새 행사 개최가 24시간 제한돼요. 자연 종료·빈 행사 취소는 제외돼요.": "You ended an event early in the last 7 days. If you end another event with approved participants early, you won’t be able to host new events for 24 hours. Events that end on their own and cancelled empty events don’t count.",
  "칠링 개최는 최근 24시간 기준 {0}회, 최근 7일 기준 {1}회 남았어요. 취소해도 개최 횟수는 돌아오지 않아요.": "You can host {0} more Chilling meetups in the rolling 24-hour window and {1} more in the rolling 7-day window. Cancelling doesn’t give them back.",
