  "위치 공유를 끄고 저장된 위치 기록을 삭제했어요.": "Location sharing is off and saved location records have been deleted.",
  "설정 변경을 저장하지 못했어요. 다시 눌러 주세요. 이 화면에서는 위치 수집을 멈췄어요.": "Couldn’t save your setting. Tap again. Location collection has stopped on this screen.",
  "이름은 비공개 계정 확인과 안전사건 대응에, 생년월일은 해당 목적과 모임의 권장 연령대 안내에, 성별은 비공개 계정 확인에 사용해요. 이름·생년월일·성별 원본은 다른 회원에게 공개하지 않으며 본인과 권한 있는 관리자만 볼 수 있어요. 설정에서 삭제하거나 탈퇴할 때까지 보관해요. 직접 입력한 내용은 실명·생년월일 인증 결과가 아니며, 입력하지 않아도 가입하거나 모임에 신청할 수 있어요.": "We use your name for private account checks and responding to safety incidents, your birth date for those same purposes and for meetup age recommendations, and your gender for private account checks. Your actual name, birth date and gender aren’t shown to other members; only you and authorized administrators can see them. We keep them until you delete them in Settings or close your account. What you enter here doesn’t verify your real name or birth date, and you can sign up and apply to meetups without it.",
