  "여러 건을 한 번에 승인하거나 입출고하려면 비즈니스 체험·유료 운영 기간이 필요해요. 한 건씩은 계속 이용할 수 있어요.": "Batch approvals and stock moves need an active business trial or paid plan. You can still handle items one at a time.",
  "출고할 수량이 현재 재고보다 많아요.": "That’s more than you have in stock.",
  "이전 입출고 요청과 내용이 달라요. 기록을 새로 확인한 뒤 다시 입력해 주세요.": "This doesn’t match your previous stock request. Refresh the records and enter it again.",
  "이전 입출고 요청을 안전하게 저장·확인하지 못했어요. 저장 공간을 확인한 뒤 같은 요청을 다시 확인해 주세요.": "Couldn’t safely save or check your previous stock request. Check your device storage, then review the same request again.",
  "결과를 확인하지 못한 이전 입출고 요청을 복구했어요. 아래에서 같은 요청을 다시 확인해 주세요.": "We restored a previous stock request whose result wasn’t confirmed. Review that request below.",
