  "기본 질문 1개 · 신청자의 프로필과 함께 확인해요.": "One default question · you’ll see answers alongside each applicant’s profile.",
  "상세 집결 장소는 승인된 멤버에게 그룹 채팅으로 안내해 주세요. 개최 시 내 모임 프로필은 행사에서 볼 수 있어요.": "Share the exact meeting point with approved members in the group chat. When you host, your meetup profile appears on the event.",
  "관리자 계정 · 모임 자리 제한 없음": "Admin account · unlimited meetup slots",
  "동시 모임 자리 {0}개를 모두 사용 중이에요. 모임을 종료하거나 나가면 자리는 바로 돌아와요.": "You’re using all {0} meetup slots. A slot frees up as soon as you end or leave a meetup.",
  "동시 모임 자리 {0}/{1} 사용 중 · 남은 자리 {2}개": "Meetup slots {0}/{1} used · {2} available",
