  "정기모임": "Groups",
  "모임을 종료하거나 나가면 자리는 바로 돌아와요.": "Spots come back as soon as a meetup ends or you leave.",
  "멤버": "Members",
  "공개할 때": "When I host",
  "누가 무엇을 보나요": "Who sees what",
  "모임 이름 · 사진 · 소개 · 신청 답변": "Meetup name · photos · intro · your answer",
  "모임 이름, 그리고 사진 · 짧은 소개": "Meetup name, plus photos · short intro",
  "모임 이름만": "Meetup name only",
  "다른 신청자": "Other applicants",
  "보이지 않아요": "Can't see anything",
  "상대가 이미 본 내용이나 저장한 사진은 되돌릴 수 없어요.": "Once someone has seen your info or saved a photo, it can't be taken back.",
  "자세히": "Details",
  "프로필을 고쳐도 이미 보낸 신청은 그대로예요.": "Editing your profile won't change applications you've already sent.",
  "신청이 취소·거절되거나 탈퇴·차단·모임 종료가 되면 그 뒤로는 새로 볼 수 없어요.": "After an application is cancelled or declined, or someone leaves, is blocked or the meetup ends, it can't be viewed again.",
  "보내면 이렇게 공유돼요": "What gets shared",
  "모임 프로필 · 신청 답변": "Meetup profile · your answer",
  "승인된 뒤 멤버": "Members, once you're approved",
  "모임 이름 · 사진 · 짧은 소개": "Meetup name · photos · short intro",
  "모임 이름만 · 사진·소개 공유는 프로필에서 바꿀 수 있어요": "Meetup name only · change photo and intro sharing in your profile",
  "이 호스트에게 모임 프로필과 답변을 보내는 데 동의해요": "I agree to send my meetup profile and answer to this host",
  "다른 신청자에게는 보이지 않아요. 취소·거절·탈퇴·차단·모임 종료 뒤에는 새로 볼 수 없지만, 이미 본 내용은 되돌릴 수 없어요.": "Other applicants can't see it. It can't be viewed again after a cancellation, decline, leave, block or the meetup ending, but anything already seen can't be taken back.",
  "신청 취소는 이 화면에서 할 수 있어요. 안전을 위해 자동 분석과 권한 있는 운영자 검토가 적용돼요.": "You can cancel your application on this screen. For safety, automated checks and authorized staff reviews apply.",
  "신청 당시": "As sent",
  "이름·사진·소개·답변은 신청할 때 보낸 그대로예요. 그 뒤에 프로필을 고쳐도 여기는 바뀌지 않아요.": "Name, photos, intro and answer are exactly as sent. Later profile edits don't change this.",
  "승인하면": "If you approve",
  "이 모임의 멤버가 되고 모임 대화에 들어와요.": "They become a member and join the meetup chat.",
  "정원이 찼거나 참여할 수 있는 모임 수를 넘으면 승인할 수 없어요.": "You can't approve if the meetup is full or they're over their meetup limit.",
  "모임·대화 규칙": "Meetups and chats",
  "운영+참여 합산": "Hosting + joining combined",
  "방장이 승인한 뒤부터 자리를 차지해요. 끝나거나 나가면 바로 돌아와요.": "A spot is used once the host approves you. It comes back as soon as the meetup ends or you leave.",
  "바로 시작": "Start right away",
  "요청하고 수락받을 필요가 없어요. 끝내도 자리가 잠기지 않아요.": "No request or accept step. Ending a chat doesn't lock a spot.",
  "스스로 나가기": "Leaving meetups",
  "24시간 안에 3번째부터 12시간 참여 제한": "3rd leave in 24 hours pauses joining for 12 hours",
  "승인된 서로 다른 모임 기준이에요. 모임이 자연스럽게 끝났거나, 승인 전에 취소했거나, 호스트가 내보낸 경우는 세지 않아요.": "Counts approved, different meetups. Meetups that ended on their own, requests cancelled before approval and removals by a host don't count.",
  "24시간 3번 · 7일 10번까지": "Up to 3 per 24 hours · 10 per 7 days",
  "취소해도 연 횟수에 들어가요. 참가자가 있는 행사를 일찍 해산하면 7일 안에 두 번째부터 24시간 동안 새로 열 수 없어요. 무료·유료 모두 같아요.": "Cancelled events still count. From the 2nd early end of an event with attendees within 7 days, you can't host new ones for 24 hours. Same for free and paid plans.",
  "차단·신고, 과도한 연락을 막는 전송 속도 제한은 모든 등급에 적용돼요.": "Blocking, reporting and send-rate limits against spam apply on every plan.",
  "크레딧 충전": "Buy credits",
  "무료 회원도 살 수 있어요.": "Free members can buy them too.",
  "글 고르고 추가 노출 선택": "Pick a post and extra views",
  "원래 보이는 만큼(자연 노출)은 크레딧에서 빠지지 않아요.": "Views your post gets on its own don't use credits.",
  "추가 노출을 다 채우면 끝": "Ends when the extra views are delivered",
  "중간에 멈추면 남은 만큼 크레딧으로 돌려받아요.": "Stop early and the rest comes back as credits.",
  "요청은 계속 받아요. 자리가 생기면 수락할 수 있고, 홍보도 그대로 진행할 수 있어요.": "You'll still get requests and can accept them once a spot opens. Your promotion can keep running.",
  "지금 수락할 수 있는 대화 수를 확인하지 못했어요. 홍보를 시작해도 대화 자리가 늘지는 않아요.": "Couldn't check how many chats you can accept. Promoting doesn't add chat spots.",
  "문의나 거래가 생긴다고 보장하지는 않아요.": "Promotion doesn't guarantee messages or sales.",
  "{0} 기준 · 끝나면 새 신청을 받지 않아요.": "{0} · no new requests after it ends.",
