  "중복을 막기 위해 재발행하지 않아요. 실제 카페 글을 확인한 뒤 운영자에게 결과 확인을 요청해 주세요.": "We won’t republish, to avoid duplicates. Check the post on the café, then ask support to confirm the result.",
  "· 카페 가입·게시 권한과 사진을 확인한 뒤 원고를 다시 저장·승인해 주세요.": "· Check café membership, posting access and photos, then save and approve the draft again.",
  "프로필을 불러오지 못했어요. 비즈니스 권한과 연결 상태를 확인해 주세요.": "Couldn’t load the profile. Check your business access and connection.",
  "사진을 준비하지 못했어요. JPEG, PNG, WebP 사진으로 다시 선택해 주세요.": "Couldn’t prepare the photo. Choose a JPEG, PNG or WebP photo instead.",
  "프로필 사진을 저장했어요. 공개 가능한 비즈니스 프로필에 표시돼요.": "Profile photos saved. They’ll show on your business profile once it can be public.",
  "다른 곳에서 프로필이 바뀌었어요. 선택한 사진은 남아 있어요. 최근 저장본을 확인하려면 취소 후 다시 열어주세요.": "The profile was changed somewhere else. Your selected photos are still here. To see the latest saved version, cancel and reopen.",
  "계정이 바뀌었어요. 현재 계정으로 다시 열어주세요.": "Your account changed. Reopen this with your current account.",
  "저장을 확인하지 못했어요. 사진은 남아 있으니 같은 내용으로 다시 시도해 주세요.": "Couldn’t confirm the save. Your photos are still here, so try again with the same details.",
  "공개 전화번호와 영업시간을 저장했어요.": "Public phone number and opening hours saved.",
  "다른 곳에서 프로필이 바뀌었어요. 입력한 연락 정보는 남아 있어요. 수정 취소 후 최근 저장본을 다시 확인해 주세요.": "The profile was changed somewhere else. Your contact details are still here. Cancel editing and check the latest saved version.",
  "전화번호는 국가번호와 숫자, 공백·괄호·하이픈으로 적어주세요. 영업시간은 500자 이내로 입력해 주세요.": "Phone numbers can use a country code, digits, spaces, brackets and hyphens. Opening hours can be up to 500 characters.",
  "연락 정보 저장을 확인하지 못했어요. 입력한 내용은 남아 있으니 다시 시도해 주세요.": "Couldn’t confirm your contact details were saved. What you entered is still here, so try again.",
