  "후기를 불러오지 못했어요. 비즈니스 소유 확인과 계정 권한을 다시 확인해 주세요.": "Couldn’t load reviews. Check your business ownership verification and account permissions.",
  "받은 후기": "Reviews you’ve received",
  "새로 확인": "Refresh",
  "이용 리뷰는 미인증 의견도 확인할 수 있어요. 근무 리뷰는 근무 증빙 인증 후에만 보이며, 증빙 원본은 비즈니스에 공개되지 않아요. 공개 평균은 종류별 인증 후기만 따로 계산해요.": "You can see unverified customer reviews here too. Employee reviews only appear after employment is verified, and the original proof is never shown to the business. Public averages are calculated separately for each type, from verified reviews only.",
