  "후기를 저장했어요. 근무 증빙 확인 전에는 나에게만 보여요.": "Review saved. Only you can see it until your employment proof is verified.",
  "후기를 저장했어요. 영수증 확인 전에는 비즈니스에만 전달돼요.": "Review saved. Only the business can see it until your receipt is verified.",
  "후기를 나에게만 저장했어요. 근무 증빙 인증 후에 공개돼요.": "Review saved privately. It’ll go public once your employment is verified.",
