  "직접 이용한 경험을 남겨 주세요.": "Share your own experience with this business.",
  "{0} 후기글, 선택 입력, 최대 300자": "{0} review, optional, up to 300 characters",
  "{0} 인증": "{0} verification",
  "(공개하려면 필수)": "(required to publish)",
  "관리자가 실제 근무 증빙을 확인한 후기만 공개돼요. 확인 전에는 나에게만 보이고 공개 평균에도 포함되지 않아요. 증빙 원본은 작성자와 권한 있는 관리자만 확인해요.": "Only reviews whose employment proof an admin has checked are published. Until then, only you can see yours, and it doesn’t count toward public averages. Only you and authorized admins can see the original proof.",
  "인증한 후기만 다른 사용자에게 공개돼요. 영수증 사진은 검토 관리자만 확인하며 공개되지 않아요.": "Only verified reviews are shown to other users. Receipt photos are only seen by the admins reviewing them and are never public.",
  "재직증명서·근로계약서·급여명세서 중 회사명, 본인 이름, 근무 기간을 확인할 수 있는 사진 1장을 제출해 주세요. 주민등록번호·계좌번호·주소·급여액 등 불필요한 정보는 가려 주세요.": "Submit 1 photo of an employment letter, contract or pay stub that shows the company name, your name and your dates of employment. Cover anything else, like your national ID number, account numbers, address or pay.",
  "비즈니스명·이용 날짜가 보이게 제출하고, 이름·전화번호·카드번호는 가려 주세요.": "Make sure the business name and date are visible, and cover your name, phone number and card number.",
