  "글을 열지 못했어요. 현재 계정의 비즈니스 권한과 연결 상태를 확인해 주세요.": "Couldn’t open the post. Check this account’s business access and connection.",
  "비즈니스의 글과 사진": "Business posts and photos",
  "연결된 글을 열어서 수정·삭제할 수 있어요. 사진을 추가하거나 순서를 바꾸면 첫 사진이 대표 사진이 돼요. 비즈니스에서 관리하려면 소유 확인을 먼저 완료해 주세요.": "Open a linked post to edit or delete it. If you add or reorder photos, the first one becomes the cover. To manage it as the business, verify ownership first.",
