  "카페의 가입·게시 규칙을 확인한 뒤 직접 올려주세요. 아래 주소는 직접 올린 글을 관리하기 위한 기록이에요.": "Check the café’s membership and posting rules, then post it yourself. The address below is just for keeping track of what you posted.",
