  "공헌이익은 입력한 변동 비용을 뺀 금액이에요. 임대료·인건비·세금 등을 반영하기 전이므로 순이익과 달라요.": "Contribution margin is what’s left after the variable costs you entered. It doesn’t include rent, wages, taxes and so on, so it isn’t net profit.",
