  "이전 입출고 요청을 확인해야 새 수량을 입력할 수 있어요.": "Check your previous stock request before entering a new amount.",
  "이 계정·비즈니스의 이전 입출고 요청을 확인하고 있어요.": "Checking the previous stock request for this account and business…",
  "입출고 요청 다시 확인": "Check stock request again",
  "같은 입출고 요청 재확인": "Recheck the same stock request",
  "입출고 요청을 보관했어요. 결과가 확인될 때까지 수량과 사유는 고정돼요. 매장을 바꾸거나 앱을 다시 열어도 같은 요청 재확인 버튼으로 원래 요청의 결과를 확인할 수 있어요.": "We’ve saved your stock request. The amount and reason are locked until the result is confirmed. Even if you switch stores or reopen the app, tap Recheck the same stock request to see the original result.",
  "비즈니스 멤버십": "Business membership",
