  "편 · 끌어올리기": " posts · Bumps",
  "전체 30편에 운영대행 신규 4편이 포함돼요. 대행 끌어올리기 8회와 보고서 1회도 함께 써요.": "Your 30 posts include 4 managed new posts. Managed work also includes 8 bumps and 1 report.",
  "에 사용량이 초기화돼요. 직원과 AI도 같은 비즈니스 한도를 공유해요.": " is when usage resets. Staff and AI share the same business limit.",
  "멤버십 사용량을 확인하지 못했어요. 비즈니스 연결 상태를 확인하고 다시 열어 주세요.": "Couldn’t check membership usage. Check your business connection and reopen this screen.",
  "같은 홍보글은 새 글로 다시 올리지 않고 기존 글을 수정하거나 끌어올려 주세요. 앱의 멤버십 → 비즈니스에서 스토어 상품이 준비되면 가입할 수 있어요.": "Don’t repost the same promo as a new post. Edit or bump the existing one instead. You can sign up under Membership → Business in the app once store products are ready.",
  "비즈니스 이용 상태": "Business access status",
  "기본 이용": "Basic access",
