  "개별 초안·승인, 원가 계산, 품목별 입출고를 계속 이용할 수 있어요.": "You can keep using single drafts and approvals, cost calculation and per-item stock in/out.",
  "체험·기존 운영 기간 또는 비즈니스 유료 멤버십에서는 여러 건을 한 번에 승인하거나 입출고할 수 있어요. 기간이 끝나도 저장한 자료는 남아요. 개인 멤버십과 비즈니스 구독은 별도로 관리해요.": "During a trial, an existing access period or a paid business membership, you can approve or log stock for several at once. Your saved data stays when the period ends. Personal membership and business subscriptions are managed separately.",
