  "스토어에서 구매 가능한 구독 상품을 받지 못했어요. 최신 테스트 앱과 스토어 계정을 확인한 뒤 다시 시도해 주세요.": "Couldn’t get subscriptions from the store. Make sure you have the latest test build and the right store account, then try again.",
  "구독 상품을 불러오지 못했어요. 현재 멤버십은 계속 이용할 수 있어요.": "Couldn’t load subscription options. You can keep using your current membership.",
  "멤버십 정보를 확인하지 못했어요. 잠시 후 다시 확인해 주세요.": "Couldn’t check your membership. Try again in a moment.",
  "이미 다른 스토어에서 구독 중이에요. 구독 관리에서 변경해 주세요.": "You’re already subscribed through another store. Make changes in Manage subscription.",
  "구매를 확인하고 있어요. 잠시 후 다시 확인해 주세요.": "Checking your purchase. Check back in a moment.",
  "현재 활성 구독은 없어요. 이전 구매의 승인 대기 상태는 결제한 스토어에서 확인해 주세요.": "No active subscription. If an earlier purchase is waiting for approval, check the store you paid with.",
  "복원할 활성 구독이 없어요.": "There’s no active subscription to restore.",
  "구독 상태를 확인했어요. 변경 예약은 스토어의 적용일에 반영돼요.": "Subscription checked. Scheduled changes take effect on the date set by the store.",
  "구매를 복원했어요.": "Purchases restored.",
  "구매를 취소했어요. 현재 멤버십은 그대로 유지돼요.": "Purchase cancelled. Your membership hasn’t changed.",
  "스토어에서 결제 승인을 기다리고 있어요. 승인되면 멤버십이 반영돼요.": "Waiting for the store to approve your payment. Your membership will update once it’s approved.",
  "스토어 처리는 완료됐지만 멤버십 반영을 확인하지 못했어요. 다시 결제하지 말고 잠시 후 다시 확인해 주세요.": "The store finished processing, but we couldn’t confirm your membership yet. Don’t pay again. Check back in a moment.",
  "새 멤버십 연결을 준비 중이에요. 현재 구독은 그대로 이용할 수 있어요.": "We’re setting up your new membership. You can keep using your current subscription.",
  "비즈니스 소유 확인과 구독 연결을 확인해 주세요. 결제 내역이 있다면 다시 결제하지 말고 구매 복원을 이용해 주세요.": "Check that business ownership is verified and the subscription is connected. If you’ve already paid, use Restore purchases instead of paying again.",
  "구독을 처리하지 못했어요. 결제 내역이 있다면 구매 복원을 이용해 주세요.": "Couldn’t process the subscription. If you’ve already paid, use Restore purchases.",
  "확인한 취소·거절 내용을 반영했어요. 새 구매는 구독하기에서 따로 진행해 주세요.": "We’ve applied the cancellation or decline you confirmed. To buy again, start a new purchase from Subscribe.",
  "현재 구독 상태를 확인했어요. 결제 내역은 구독 관리에서 확인해 주세요.": "Subscription status checked. See your payment history in Manage subscription.",
  "계정과 구독 상태를 확인하지 못했어요. 구매 대기는 유지돼요. 잠시 후 다시 확인해 주세요.": "Couldn’t check your account and subscription. Your purchase is still pending. Try again in a moment.",
  "구독 관리를 열지 못했어요. 결제한 스토어에서 구독을 확인해 주세요.": "Couldn’t open subscription settings. Check your subscription in the store where you paid.",
