  "홍보 크레딧": "Promotion credits",
  "후기와 평가 상태를 불러오지 못했어요.": "Couldn’t load your reviews and ratings.",
  "뒤로": "Back",
  "모임 후기 · 내 글링 리뷰": "Meetup reviews · My Gling reviews",
  "참여한 회차": "Sessions attended",
  "종료 후 7일 안에 참석 확인과 평가를 남길 수 있어요. 모임 퇴장·차단 이후에도 이미 참여한 회차의 권한은 유지돼요.": "You can confirm attendance and leave a rating up to 7 days after a session ends. You keep this for sessions you attended, even if you later leave the meetup or block someone.",
  "불러오는 중…": "Loading…",
  "아직 등록된 참여 회차가 없어요. 모임 화면에서 회차를 열고 실제 현장에 체크인해주세요.": "No sessions yet. Open a session from the meetup screen and check in when you’re there in person.",
  "참석·개인 평가": "Attendance and private ratings",
  "후기·참석 확인": "Reviews and attendance",
  "받은 글링 리뷰": "Gling reviews you’ve received",
  "양쪽 제출 또는 7일 경과 후 검토된 결과만 보여요. 작성자와 개인 원문은 공개하지 않아요. 이의제기한 평가는 검토 중 점수에서 제외돼요.": "Reviews appear only after both of you submit or 7 days pass, and only once they’ve been checked. Reviewers and their private comments are never shown. Disputed reviews don’t count toward your score while under review.",
  "현재 공개 시점에 도달한 평가가 없어요.": "No reviews are ready to show yet.",
  "최신 상태 다시 확인": "Refresh status",
  "접수 결과를 확인하지 못했어요. 입력은 유지했어요. 최신 상태를 확인해주세요.": "Couldn’t confirm your submission. We kept what you entered. Check the latest status.",
  "실제 만남": "In-person meeting",
  "검토 중 · 집계 제외": "Under review · Not counted",
  "반영된 리뷰": "Review counted",
  "리뷰에 이의제기": "Dispute review",
  "사용자 리뷰 이의제기 사유": "Reason for disputing the user review",
  "사실관계·맥락을 적어주세요. (10자 이상)": "Explain what happened and any context. (At least 10 characters)",
  "접수 중…": "Submitting…",
  "운영팀에 검토 요청": "Ask our team to review",
  "대기 구매가 취소·거절됐나요?": "Was the pending purchase cancelled or declined?",
  "결제한 스토어에서 이전 요청의 취소 또는 거절 완료 안내를 확인한 경우에만 계속해 주세요. 빈 구독 목록만으로는 확인할 수 없어요. 승인 대기가 남아 있으면 다시 구매할 때 중복 청구될 수 있어요.": "Only continue if the store you paid with has confirmed the earlier request was cancelled or declined. An empty subscription list doesn’t confirm this. If approval is still pending, buying again could charge you twice.",
  "아직 확인 못 했어요": "Not yet",
  "취소·거절 확인 완료": "Yes, it’s confirmed",
  "로그인 확인 중": "Checking sign-in",
  "일반": "Personal",
  "비즈니스별로 글링 안의 홍보글을 관리해요. 개인 멤버십과 별도예요.": "Manage each business’s promotional posts on Gling. This is separate from your personal membership.",
  "확인된 비즈니스 소유자만 구독을 연결할 수 있어요.": "Only verified business owners can connect a subscription.",
  "결제 연결은 다른 비즈니스에 묶여 있어요. 해당 비즈니스를 선택해 주세요.": "This payment is linked to a different business. Select that business.",
  "기존 구독을 이 비즈니스에 연결": "Connect your existing subscription here",
  "내 멤버십": "My membership",
  "무료": "Free",
  "갱신 예정": "(renews)",
  "까지 이용 가능": "(access ends)",
  "이용 기간 종료 예정": "(ends)",
  "관리자 계정 · 모임을 제한 없이 이용해요.": "Admin account · Unlimited meetups.",
  "기존 구독 가격과 더 빠른 끌어올리기 혜택을 유지해요.": "You keep your current price and faster bumps.",
  "다시 확인하기": "Check again",
  "스토어의 취소·거절 완료 안내를 확인해 주세요. 빈 구독 목록만으로는 확인할 수 없어요. 승인 대기가 계속되면 다시 구매하지 마세요.": "Check that the store has confirmed the cancellation or decline. An empty subscription list doesn’t confirm this. If approval is still pending, don’t buy again.",
  "스토어 구독 관리 열기": "Open store subscriptions",
  "스토어의 취소 또는 거절을 확인한 경우에만 구매 대기를 해제해요.": "Only clear the pending purchase once the store confirms it was cancelled or declined.",
  "스토어에서 대기 구매 취소·거절을 확인했어요": "I confirmed the pending purchase was cancelled or declined in the store",
  "사용 현황": "Usage",
  "지금 이 순간 기준": "As of now",
  "오늘 이야기 글, 횟수 제한 없음": "Today’s stories, unlimited posts",
  "오늘 이야기 글": "Today’s stories",
  "횟수 제한 없음": "Unlimited posts",
  "모임을 숫자와 무관하게 이용해요.": "No limit on meetups.",
  "이용 규칙": "Usage rules",
  "필요할 때만 펼쳐 보세요": "Expand when you need the details",
  "자리 사용 · 반복 이용 제한 안내": "Slots · Repeat-use limits",
  "모임은 동시에 운영·참여하는 개수를 합산해요. 참여는 방장 승인 후 자리를 사용해요. 1:1 대화는 요청·수락 없이 바로 시작해요.": "Meetups you host and join at the same time all count toward your slots. Joining uses a slot once the host approves. Direct chats start right away, with no request or acceptance needed.",
  "모임 종료·퇴장 시 자리는 바로 돌아와요. 최근 24시간에 승인된 서로 다른 모임에서 자진 퇴장 3회째부터 새 참여가 12시간 제한돼요. 자연 종료·승인 전 취소·강퇴는 제외돼요.": "You get your slot back as soon as a meetup ends or you leave. If you leave 3 or more different approved meetups within 24 hours, you can’t join new ones for 12 hours. Meetups ending normally, cancelling before approval and being removed by the host don’t count.",
  "칠링 개최는 최근 24시간 3회·7일 10회까지예요. 취소해도 개최 횟수는 유지돼요. 참가자가 있는 행사 조기 해산은 최근 7일 2회째부터 새 개최가 24시간 제한돼요. 무료·유료에 동일하게 적용돼요.": "You can host Chilling up to 3 times in 24 hours and 10 times in 7 days. Cancelling still counts toward this. If you end a Chilling with participants early 2 or more times in 7 days, you can’t host a new one for 24 hours. These rules are the same on free and paid plans.",
  "1:1 대화를 종료해도 자리 잠금이 없어요. 차단·신고와 과도한 연락을 막는 전송 속도 제한은 모든 등급에 적용돼요.": "Ending a direct chat doesn’t lock a slot. Blocking, reporting and rate limits that prevent excessive messaging apply on every plan.",
  "모임 종료·퇴장 시 자리는 바로 돌아와요. 최근 24시간에 승인된 서로 다른 모임에서 자진 퇴장 3회째부터 새 참여가 12시간 제한돼요. 자연 종료·승인 전 취소·호스트가 내보낸 경우는 제외돼요.": "Meetup slots return immediately when you end or leave. Voluntarily leaving 3 different approved meetups within 24 hours restricts new joining for 12 hours. Natural endings, pre-approval cancellations and removals by a host do not count.",
  "이번 달 사용": "Used this month",
