  "같은 내용은 새 글로 다시 올릴 수 없어요. 기존 글을 수정하거나 끌어올려 주세요. 끌어올리기는 모든 글을 합쳐 무료 5일, 플러스 이틀, 프로 하루, 프리미엄 12시간에 한 번이에요.": "You can’t repost the same content as a new post. Edit or bump the existing one instead. Bumps are shared across all your posts: once every 5 days on Free, every 2 days on Plus, daily on Pro and every 12 hours on Premium.",
