  "잠금 화면에 보낸 사람과 짧은 메시지가 표시돼요. 사진은 사진 안내만 보여요.": "Your lock screen shows the sender and a short preview. For photos, it just says a photo was sent.",
  "보낸 사람과 내용 없이 “메시지가 도착했어요.”만 표시돼요.": "Shows only “You have a new message.” with no sender or content.",
