  "관심사와 내 도시": "Interests and city",
  "의 맛집·레스토랑, 가볼 만한 곳·행사와 새 글·모임 소식을 골라 받을 수 있어요. 이사 후 선호 지역을 바꾸면 알림 지역도 함께 바뀝니다.": "Pick updates on restaurants, places to go, events, new posts and meetups. If you move and change your preferred city, your notification city changes too.",
