  "크레딧": "Credits",
  "{0}에 구매": "Buy for {0}",
  "내 글 끌어올리기": "Promote my post",
  "게시글 홍보를 준비하고 있어요. 시작할 수 있게 되면 보관한 크레딧을 사용할 수 있어요.": "Post promotion is coming soon. You can use your credits once it launches.",
  "지금 홍보할 수 있는 내 글이 없어요. 글을 게시한 뒤 여기에서 선택해 주세요.": "You don’t have any posts to promote right now. Publish a post, then choose it here.",
  "추가 홍보 노출": "Extra impressions",
  "자연 노출은 차감하지 않아요. 구매한 추가 노출을 채우면 홍보가 종료돼요. 문의나 거래 성사를 보장하지는 않아요.": "Organic impressions don’t use credits. Your promotion ends once the extra impressions you bought are delivered. Inquiries or completed sales aren’t guaranteed.",
  "새 대화 수락 가능 {0}개": "You can accept {0} new chats",
  "대화 자리 확인 준비 중": "Checking chat slots…",
  "현재 수락할 수 있는 대화 수를 확인할 수 없어요. 홍보 시작으로 대화 자리가 추가되지는 않아요.": "Couldn’t check how many chats you can accept. Promoting a post doesn’t add chat slots.",
  "지금은 새 대화를 수락할 자리가 없어요. 요청은 받을 수 있지만, 자리가 생긴 뒤 수락할 수 있어요. 홍보는 계속할 수 있어요.": "You don’t have a free chat slot right now. You can still get requests and accept them once a slot opens. Your promotion can keep running.",
