  "소셜 계정으로 로그인했어요. 이름과 나이는 아직 확인되지 않았어요.": "You signed in with a social account. Your name and age aren’t verified yet.",
  "앱에 등록된 현재 단계예요. 전화번호·신분증 확인 기록은 앱에서 조회할 수 없어요.": "This is your current level in the app. Phone and ID verification records can’t be viewed in the app.",
  "확인된 조건 · 소셜 계정 로그인": "Verified · Social account sign-in",
  "현재 등록된 단계 · Lv": "Current level · Lv",
