  "지난 단계": "Previous level",
  "지금은 앱에서 신청할 수 없어요.": "You can’t apply in the app right now.",
  "인증 단계가 의미하는 것": "What verification levels mean",
  "확인된 항목만 표시해요. 인증 단계는 만남의 안전이나 상대방의 행동을 보증하지 않아요. 이름·생년월일을 직접 입력해도 인증 단계는 올라가지 않아요.": "Only verified details are marked. A verification level doesn’t guarantee a safe meetup or how someone will behave. Entering your own name or birth date doesn’t raise your level.",
