  "공개한 글 이력이에요. 거래 완료는 작성자가 표시한 상태이며 실제 거래·신원 인증을 보장하지 않아요.": "Posts they’ve made public. “Completed” is set by the poster and doesn’t confirm a real trade or anyone’s identity.",
  "이전 글 더 보기": "Load earlier posts",
  "로그인을 완료하지 못했어요. 원래 링크에서 다시 시도해주세요.": "Couldn’t finish signing in. Try again from the original link.",
  "로그인 응답을 확인하지 못했어요. 원래 링크에서 다시 시도해주세요.": "Couldn’t verify the sign-in. Try again from the original link.",
