  "소셜 계정으로 글링에 로그인하면 적용돼요. 소셜 로그인만으로 실명이나 나이가 확인되지는 않아요.": "Applies when you sign in to Gling with a social account. Social sign-in alone doesn’t verify your legal name or age.",
  "전화번호 확인": "Phone verification",
