  "이름에 \"글링\"을 쓰고, 서버 주소 칸에 아래 주소를 붙여 넣은 뒤 Continue → Add를 눌러요.": "Name it \"Gling\", paste the address below as the server URL, then choose Continue → Add.",
  "글링으로 로그인": "Sign in with Gling",
  "Claude 커넥터 목록에서 글링 옆 Connect를 누르면 글링 로그인 창이 떠요. 연결할 비즈니스에 체크하고 연결하면 끝이에요. 연결은 Claude에서 시작해야 해서 이 페이지에는 연결 버튼이 없어요.": "In Claude’s connector list, click Connect next to Gling and a Gling sign-in window opens. Tick the business you want to connect and you’re done. The connection has to start in Claude, so there’s no connect button on this page.",
  "무료 요금제는 커넥터를 1개까지 추가할 수 있어요. 팀 요금제에서 \"already exists\"가 뜨면 이미 추가돼 있는 거예요. 다시 추가하지 말고 목록의 글링에서 Connect를 눌러요.": "The free plan allows one custom connector. On a Team plan, “already exists” means Gling has already been added. Don’t add it again; click Connect on Gling in the list.",
  "플러그인 화면 열기": "Open the plugins screen",
  "웹 브라우저에서 ChatGPT 플러그인 화면을 열고 + → Add custom MCP server를 눌러요.": "In a web browser, open ChatGPT's plugins screen and choose + → Add custom MCP server.",
  "ChatGPT 플러그인 화면 열기": "Open ChatGPT plugins",
  "이름에 \"글링\"을 쓰고 Server URL에 아래 주소를 붙여 넣어요. 인증 칸은 비워 두고 Create as a plugin을 눌러요.": "Name it \"Gling\" and paste the address below as the Server URL. Leave authentication empty and choose Create as a plugin.",
  "설치한 뒤 대화창에서 @글링을 부르면 로그인 창이 떠요. 연결할 비즈니스와 권한을 고르면 끝이에요.": "After installing, mention @Gling in a chat and a sign-in window opens. Pick the business and permissions and you're done.",
  "ChatGPT는 요금제에 따라 이 메뉴가 보이지 않을 수 있어요.": "Depending on your ChatGPT plan, this menu may not appear.",
  "터미널에 붙여 넣기": "Paste into the terminal",
  "Claude Code가 설치된 컴퓨터의 터미널에서 실행해요.": "Run this in a terminal on the computer where Claude Code is installed.",
  "Claude Code를 열고 /mcp를 입력한 뒤 gling을 골라 로그인해요.": "Open Claude Code, type /mcp, choose gling and sign in.",
  "비즈니스 고르기": "Choose the business",
  "브라우저에 뜬 글링 화면에서 연결할 비즈니스와 권한을 고르면 끝이에요.": "Pick the business and permissions on the Gling page that opens in your browser, and you're done.",
  "Codex가 설치된 컴퓨터의 터미널에서 실행해요.": "Run this in a terminal on the computer where Codex is installed.",
