  "구매 후 잔액을 확인하지 못했어요. 다시 결제하지 말고 잠시 후 새로 확인해 주세요.": "Couldn’t check your balance after the purchase. Don’t pay again — refresh in a moment.",
  "구매 상태를 확인하지 못했어요. 결제 승인 또는 크레딧 반영을 기다리고 있다면 다시 결제하지 마세요.": "Couldn’t check your purchase. If you’re waiting for payment approval or credits to appear, don’t pay again.",
  "홍보를 시작했어요. 추가 홍보 노출은 아래에서 확인할 수 있어요.": "Your promotion is live. See the extra views below.",
  "사용 가능한 크레딧이 부족해요. 잔액을 확인해 주세요.": "You don’t have enough credits. Check your balance.",
  "홍보 시작을 확인하지 못했어요. 같은 글과 수량으로 다시 시도하면 이전 요청을 이어서 확인해요.": "Couldn’t confirm your promotion started. Try again with the same post and amount, and we’ll pick up your earlier request.",
  "홍보를 중단했어요. 사용하지 않은 크레딧은 잔액으로 돌아와요.": "Promotion stopped. Unused credits go back to your balance.",
  "홍보 중단을 확인하지 못했어요. 새로 확인한 뒤 다시 시도해 주세요.": "Couldn’t confirm the promotion stopped. Refresh and try again.",
  "이용 상태를 확인하지 못했어요. 실제 제한 여부는 요청할 때 다시 확인해요. 신고·차단·나가기는 가능해요.": "Couldn’t check your account status. Any limits are checked again when you send a request. You can still report, block or leave.",
  "확인을 저장했어요. 상대의 확인을 기다려주세요.": "Saved. Now waiting for them to confirm too.",
  "체크인했어요. 종료 후 서로 참석을 확인해주세요.": "You’re checked in. Confirm each other’s attendance after the meetup ends.",
  "운영팀에 참석 검토를 요청했어요. 자동으로 참석 인증되지 않아요.": "We’ve asked the Gling team to review your attendance. It isn’t verified automatically.",
  "후기를 제출했어요. 검토 후 모임에 반영됩니다.": "Review sent. It’ll appear on the meetup after it’s checked.",
  "1~10점에서 0.5점 단위로 선택해 주세요.": "Choose a score from 1 to 10, in steps of 0.5.",
  "Instagram 프로필 주소를 확인해 주세요.": "Check the Instagram profile link.",
  "HTTPS 주소를 확인해 주세요.": "Check the link. It needs to start with https://.",
