  "이메일로 오픈 알림 신청": "Get launch updates by email",
  "메일 앱이 열려요. 신청 메일을 보내면 접수됩니다.": "This opens your email app. Send the email and you’re on the list.",
  "밴쿠버·토론토의 일상과 동네 정보를 한국어로 나누는 커뮤니티, 글링. 가까운 이웃의 이야기와 모임을 만날 준비를 하고 있어요.": "Gling is a Korean-language community for everyday life and local tips in Vancouver and Toronto. Neighbourhood stories and meetups are on the way.",
