  "먼저, 두 도시에서": "Starting with two cities",
  "우리가 사는 곳에서": "Every story starts",
  "이야기는 시작되니까.": "where we live.",
  "밴쿠버와 토론토부터 준비하고 있어요. 다음 도시의 출시 일정은 추후 안내할게요.": "We’re starting with Vancouver and Toronto. We’ll share dates for more cities later.",
  "우리가 지키는 것": "What we stand for",
  "생각은 자유롭게,": "Speak freely,",
  "대화는 책임 있게.": "talk responsibly.",
  "정치적 입장, 소수 의견, 운영진 비판은 제재 이유가 아닙니다. 다른 사람의 안전과 참여를 직접 해치는 행위에는 분명한 기준을 둡니다.": "Political views, minority opinions and criticism of the team are never a reason for action. We draw clear lines around anything that directly harms someone’s safety or ability to take part.",
