  "밴쿠버 · 토론토에서 시작하는 글링.": "Gling, starting in Vancouver · Toronto.",
  "운영팀에 문의하기 ↗": "Contact the team ↗",
  "비 오는 날의 산책길부터, 오늘 저녁 함께 먹을 한 끼까지.": "From rainy-day walks to someone to grab dinner with tonight.",
  "킷실라노, 버나비, 코퀴틀람, 다운타운. 가까운 생활권의 작은 질문과 일상을 나눠요.": "Kitsilano, Burnaby, Coquitlam, Downtown. Share quick questions and everyday moments close to home.",
  "출시 준비 중": "Coming soon",
  "출근길에 발견한 풍경부터, 주말에 가보고 싶은 동네까지.": "From sights on your commute to neighbourhoods to explore this weekend.",
  "노스욕, 미시사가, 영앤블루어. 넓은 도시에서도 서로의 하루를 가까이에서 나눠요.": "North York, Mississauga, Yonge and Bloor. Even in a big city, share your day with people nearby.",
  "몽루아얄 산책부터, 동네 시장에서 만난 한 끼까지.": "From walks on Mount Royal to a bite at the local market.",
  "플라토, 마일엔드, 다운타운. 한국어로 몬트리올의 생활 정보와 일상을 나눠요.": "Plateau, Mile End, Downtown. Share Montréal tips and everyday life in Korean.",
  "캘거리의 이야기도 기다리고 있어요.": "We’re looking forward to Calgary’s stories too.",
  "정착부터 동네 생활까지. 확장 일정은 아직 정해지지 않았어요.": "From settling in to everyday neighbourhood life. No launch date yet.",
  "추후 검토": "Under consideration",
  "위니펙은 앞으로 함께할 후보 도시예요.": "Winnipeg is on our list of future cities.",
  "가까운 이웃과 나누는 생활 이야기. 확장 일정은 아직 정해지지 않았어요.": "Everyday stories with neighbours nearby. No launch date yet.",
  "사스카툰의 이야기도 기다리고 있어요.": "We’re looking forward to Saskatoon’s stories too.",
  "우리 동네의 작은 질문과 만남. 확장 일정은 아직 정해지지 않았어요.": "Quick questions and meetups in your neighbourhood. No launch date yet.",
  "오타와 커뮤니티는 준비 중입니다.": "Gling for Ottawa is in the works.",
  "에드먼튼 커뮤니티는 준비 중입니다.": "Gling for Edmonton is in the works.",
  "리자이나 커뮤니티는 준비 중입니다.": "Gling for Regina is in the works.",
  "세인트존 커뮤니티는 준비 중입니다.": "Gling for Saint John is in the works.",
  "할리팩스 커뮤니티는 준비 중입니다.": "Gling for Halifax is in the works.",
  "확장 일정은 추후 안내합니다.": "We’ll share launch dates later.",
  "먼저 만날 도시": "First cities",
  "밴쿠버 · 토론토 · 몬트리올 · 에드먼튼": "Vancouver · Toronto · Montréal · Edmonton",
  "함께 나눌 주제": "Topics to share",
  "10개의 카테고리": "10 categories",
  "정치적 입장과 의견은 제한하지 않습니다.": "We don’t restrict political views or opinions.",
  "생각이 다르거나 운영진을 비판한다는 이유로 글과 계정을 제한하지 않습니다.": "We won’t restrict posts or accounts for disagreeing or criticizing the team.",
  "불법과 직접적인 괴롭힘에는 분명한 선을 둡니다.": "We draw a clear line at illegal activity and direct harassment.",
  "협박, 신상 공개, 사기, 반복적인 욕설처럼 다른 사람의 안전과 참여를 해치는 행위만 제한합니다.": "We only restrict behaviour that harms other people’s safety or ability to take part, like threats, doxxing, scams and repeated abuse.",
  "운영진의 판단도 설명하고 기록합니다.": "We explain and record our own decisions too.",
  "조치 이유를 알리고 이의를 제기할 수 있게 해 운영자가 커뮤니티 위에 서지 않도록 합니다.": "We tell you why we acted and let you appeal, so the team never stands above the community.",
  "01 · 이웃의 이야기": "01 · Neighbourhood stories",
  "작은 질문도,\n반가운 이야기가 되도록.": "Where small questions\nturn into good conversations.",
  "오늘 발견한 맛집, 처음이라 낯선 정착 질문, 취향이 닮은 모임. 글과 댓글에서 시작한 대화를 이웃과 이어가세요.": "A great spot you found today, a question about settling in, a meetup for people like you. Keep the conversation going with neighbours in posts and comments.",
  "도시별 피드와 10개의 생활 주제": "A feed for each city and 10 everyday topics",
  "글과 댓글로 나누는 동네 이야기": "Neighbourhood stories in posts and comments",
  "DM과 모임으로 이어지는 대화": "Conversations that continue in DMs and meetups",
  "02 · 가까운 동네부터": "02 · Start close to home",
  "어느 동네로\n갈까요?": "Where to\nnext?",
  "내가 사는 도시도, 다음에 가보고 싶은 도시도. 직접 동네를 골라 그곳의 이야기를 펼쳐보세요.": "The city you live in, or the one you want to visit next. Pick a neighbourhood and see its stories.",
  "밴쿠버 · 토론토 · 몬트리올 · 에드먼튼에서 시작": "Starting in Vancouver · Toronto · Montréal · Edmonton",
  "기기 위치 권한 없이 직접 도시 선택": "Pick your city yourself, no location access needed",
  "다음 도시의 일정은 추후 안내": "Dates for more cities to come",
  "보존 기간": "Retention",
  "AI 분석": "AI review",
  "이의 제기": "Appeals",
  "문의처": "Contact",
  "가입, 프로필, 글과 댓글, 대화, 신고 처리, 안전 운영에 필요한 범위의 데이터를 수집하고 사용합니다.": "We collect and use only the data needed for sign-up, profiles, posts and comments, conversations, handling reports and keeping the community safe.",
  "게시물, 메시지, 신고, 감사 로그는 목적별 기준에 따라 보존되며, 삭제 요청 경로를 함께 안내합니다.": "Posts, messages, reports and audit logs are kept for set periods based on their purpose, and we explain how to request deletion.",
  "모든 새 글·댓글·대화는 위험 탐지 대상입니다. AI는 우선순위만 보조하며 사람 검토 없이 영구 제재를 확정하지 않습니다.": "All new posts, comments and conversations are screened for risks. AI only helps us prioritize. No permanent action is final without human review.",
  "콘텐츠 숨김, 계정 제한, 신고 처리 결과에 대해 재검토를 요청할 수 있는 경로를 제품 소개 단계부터 공개합니다.": "From day one, we publish how to request a review of hidden content, account restrictions and report outcomes.",
  "운영, 정책, 개인정보 및 계정 삭제 문의는 gling@ej-entertainment.com 으로 받습니다.": "For questions about operations, policies, privacy or account deletion, email gling@ej-entertainment.com.",
