  "로그인 계정이 다르거나 연결 요청이 만료됐어요. 다시 연결해 주세요.": "You’re signed in to a different account, or the request expired. Link Naver again.",
  "네이버 계정을 다시 연결해 주세요.": "Link your Naver account again.",
  "카페의 게시판 주소를 붙여넣어 주세요. 카페 홈 주소만으로는 게시판을 선택할 수 없어요.": "Paste the URL of a café board. The café home URL alone doesn’t tell us which board to use.",
  "원고가 바뀌었어요. 최신 저장본과 사진 순서를 다시 확인하고 승인해 주세요.": "The draft has changed. Review the latest saved version and photo order, then approve it.",
  "최신 저장 원고를 먼저 승인해 주세요.": "Approve the latest saved draft first.",
