  "게시 기준에 맞지 않는 내용이에요.": "This content doesn’t meet our posting guidelines.",
  "사진 형식 또는 용량을 확인하지 못했어요. 원고의 사진을 확인해 주세요.": "Couldn’t verify a photo’s format or size. Check the photos in the draft.",
  "발행 요청을 안전하게 저장하지 못했어요. 브라우저 저장 공간을 확인해 주세요.": "Couldn’t safely save the publish request. Check your browser storage.",
  "게시 결과가 불확실해요. 중복 게시를 막기 위해 재발행을 멈췄어요. 카페에서 실제 글을 확인해 주세요.": "We’re not sure the post went through. To avoid a duplicate, we stopped republishing. Check the café to see if it’s there.",
  "중단된 비즈니스는 게시할 수 없어요.": "Paused businesses can’t publish.",
  "오늘 게시 한도 또는 연결 요청 한도에 도달했어요. 잠시 후 다시 확인해 주세요.": "You’ve hit today’s posting or connection limit. Check back in a bit.",
  "처리하지 못했어요. 입력은 유지했으니 상태를 다시 확인해 주세요.": "Something went wrong. Your input is saved, so check the status and try again.",
  "네이버 연결 해제": "Unlink Naver",
  "새 게시를 중단하고 글링에 저장한 연결 토큰을 삭제해요. 이미 카페에 올린 글은 유지돼요.": "New posts will stop and the connection token saved in Gling will be deleted. Posts already in the café stay up.",
