  "표시 조회수는 실제 열람 인원이 아닙니다. 로그인 회원과 익명 세션은 합산하지 않습니다. 비즈니스 링크 클릭은 외부 이동을 누른 기록이며 문의·지원·주문 완료는 확인하지 않았습니다. 최초 열람은 같은 글의 로그인 계정별 최초 기록만 포함하며 재방문은 포함하지 않습니다.": "Displayed views aren’t the number of people who read your posts. Signed-in members and anonymous sessions aren’t added together. Business link clicks count taps that left Gling; we haven’t confirmed any inquiries, applications or completed orders. First views count only each signed-in account’s first view of a post, not return visits.",
