  "모임에 함께할 수 있게 됐어요. 모임 채팅에서 인사해 볼까요?": "You’re in! Say hi in the meetup chat.",
  "이번에는 모임에 함께하기 어려워요. 다른 모임도 둘러보세요.": "Your request to join wasn’t accepted this time. Take a look at other meetups.",
  "모임은 어땠어요? 참석을 확인하고 함께한 경험과 매너를 남겨 주세요.": "How was the meetup? Confirm you were there, then review the experience and everyone’s conduct.",
  "새 기기 또는 브라우저에서 로그인했어요. 본인이 아니라면 계정 설정을 확인해 주세요.": "Your account was signed in on a new device or browser. If this wasn’t you, check your account settings.",
  "새 로그인이 확인됐어요. 본인이 아니라면 계정 설정을 확인해 주세요.": "We noticed a new sign-in to your account. If this wasn’t you, check your account settings.",
  "계정 이메일이 변경됐어요. 본인이 아니라면 계정 설정을 확인해 주세요.": "Your account email was changed. If this wasn’t you, check your account settings.",
  "계정 비밀번호가 변경됐어요. 본인이 아니라면 계정 설정을 확인해 주세요.": "Your account password was changed. If this wasn’t you, check your account settings.",
  "관심 있는 주제에 새 글이 올라왔어요. 한번 읽어볼까요?": "There’s a new post on a topic you follow. Take a look.",
  "우리 동네에 새 모임이 생겼어요. 어떤 모임인지 볼까요?": "There’s a new meetup near you. See what it’s about.",
  "커뮤니티 이용 규칙에 따른 경고예요. 이용 규칙을 확인해 주세요.": "You’ve received a warning under our community guidelines. Please review the guidelines.",
  "커뮤니티 이용 규칙에 따라 계정 이용이 제한됐어요. 계정 설정에서 확인해 주세요.": "Your account has been restricted under our community guidelines. See your account settings for details.",
  "외부 서비스 연결을 확인해 주세요. 비즈니스 관리에서 상태를 볼 수 있어요.": "Check your connected services. You can see their status in Business tools.",
  "게시 결과가 아직 확실하지 않아요. 다시 게시하기 전에 비즈니스 관리에서 확인해 주세요.": "We’re not sure your post went through yet. Check Business tools before posting again.",
  "게시를 마치지 못했어요. 비즈니스 관리에서 확인해 주세요.": "Your post didn’t go through. Check Business tools.",
  "내 비즈니스에 새 이용 후기가 올라왔어요. 확인해 보세요.": "Your business got a new customer review. Take a look.",
  "내 후기에 비즈니스에서 답변을 남겼어요.": "The business replied to your review.",
  "후기 증빙을 확인했어요. 이제 인증된 후기로 표시돼요.": "We checked your proof of visit. Your review now shows as verified.",
  "후기 인증이 승인되지 않았어요. 내 후기에서 이유를 확인해 주세요.": "Your review couldn’t be verified. Open your review to see why.",
  "저장한 비즈니스에 새 소식이 있어요. 한번 살펴보세요.": "A business you saved has an update. Take a look.",
  "후기나 참석 확인을 살펴봐야 해요. 관리자 화면에서 검토해 주세요.": "A review or attendance check needs a look. Review it in the admin dashboard.",
  "새 차단 내역이 있어요. 신고함에서 확인해 주세요.": "There’s a new block. Check the reports inbox.",
  "새 신고가 들어왔어요. 신고함에서 원본을 확인해 주세요.": "New report received. Check the original in the reports inbox.",
  "긴급하게 확인할 감시어가 포함돼 있어요. 지금 바로 검토해 주세요.": "Something contains an urgent watch term. Review it now.",
