  "맨 위 로고 바로 밑 줄이에요. 부동산·구인구직·중고거래처럼 주제별로 모아 보고, 끝의 '더보기'에 나머지가 있어요.": "It's the row right under the logo. Filter by topic, like housing, jobs or used items, and tap “More” at the end for the rest.",
