  "궁금한 걸 묻거나 집·일자리·중고 글을 올려요. 주제를 고르면 맞는 칸이 나와요.": "Ask a question or post a home, job or used item. Pick a topic and the right fields appear.",
  "채팅 · 알림": "Chat · Notifications",
  "채팅은 1:1 대화와 모임 단톡방, 알림은 내 글에 달린 댓글과 모임 소식이에요.": "Chat holds your 1:1 and meetup group chats. Notifications show comments on your posts and meetup updates.",
